import{_ as o,o as s,c as e,a2 as a}from"./chunks/framework.DPTp4bo7.js";const h=JSON.parse('{"title":"2.3 阻塞端与流通端：你控控我，我控控你","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/2-3-blocking-and-flowing-branches-you-control-me-i-control-you"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/2-3-blocking-and-flowing-branches-you-control-me-i-control-you"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/2-3-blocking-and-flowing-branches-you-control-me-i-control-you"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/2-3-blocking-and-flowing-branches-you-control-me-i-control-you"}]]},"headers":[],"relativePath":"zh/2-3-blocking-and-flowing-branches-you-control-me-i-control-you.md","filePath":"zh/page-Bk5lLqDsnmVVaFwefNgViT.md"}'),n={name:"zh/2-3-blocking-and-flowing-branches-you-control-me-i-control-you.md"};function r(i,t,d,l,c,p){return s(),e("div",null,[...t[0]||(t[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="_2-3-阻塞端与流通端-你控控我-我控控你" aria-hidden="true"></span><h1 id="_2-3-阻塞端与流通端-你控控我-我控控你" tabindex="-1">2.3 阻塞端与流通端：你控控我，我控控你 <a class="header-anchor" href="#_2-3-阻塞端与流通端-你控控我-我控控你" aria-label="Permalink to &quot;2\\.3 阻塞端与流通端：你控控我，我控控你&quot;">​</a></h1><blockquote><p>源页面 ID：<code>Bk5lLqDsnmVVaFwefNgViT</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Bk5lLqDsnmVVaFwefNgViT" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>从控制的角度讲，阻塞其实我们用来<strong>控制的手段</strong>。</p><p><span id="source-block-TK5U3YUOkwhUJ6sOHGvHps"></span></p><span class="logistics-source-anchor" id="分流的角度" aria-hidden="true"></span><h3 id="分流的角度" tabindex="-1">分流的角度 <a class="header-anchor" href="#分流的角度" aria-label="Permalink to &quot;分流的角度&quot;">​</a></h3><p>在我们前面的讨论中，当我们<u>从一条生产通路分为两条生产通路</u>，且其中一条形成阻塞时，这两条通路之间就形成了某种<strong>控制关系</strong>。（也可理解为因果关系）</p><p>对于两类阻塞，我们把<u><strong>我们希望</strong></u><strong>首先形成阻塞的通路称为阻塞端</strong><s>而不是因为你搭错了导致另一条路堵了变成阻塞端</s>，另一条通路称为<strong>流通端</strong>。顾名思义，阻塞端的生产速度往往会受到各个方面的<strong>外部限制</strong>，在限制发生变化时，生产速度也相应发生变化。例如，对切换型阻塞，外部限制为<u>满的库存</u>。当库存清空或者开始消耗后，阻塞端的生产又会恢复。对平衡型阻塞，外部限制为<u>阻塞限流器或产品配方的其他物料供给</u>。当阻塞限流流量数值修改，或其余物料供给情况发生变化时，阻塞端的生产速度也会变化。</p><p><strong>流通端的生产则完全由阻塞端决定</strong>，即形成阻塞时，全部或部分流量由阻塞端转向流通端生产。阻塞解除时，相应流量又转回阻塞端，使得流通端生产放缓。控制流程为：<strong>首先外部限制影响阻塞端生产，其次阻塞端生产影响流通端生产</strong>。即控制方向：</p><p><span class="mark-purple"><strong>外部限制→阻塞端→流通端</strong></span></p><p>也因此，阻塞端常常表现为依据下游阻塞的缓存空间/生产速度决定上游生产速度，而流通端则表现为依据上游所给予的材料进行生产，只要没有材料过来，它就免费了。</p><p><span class="mark-blue">我用最直白，最不绕弯子，一针见血的方式跟你说：阻塞端局部是满仓，流通端局部是空仓。满仓走了多少才能生产多少，空仓进多少就生产多少。</span></p><blockquote><p>这一性质在之后的气液反馈自适应中有重要影响，即流通端不能采用后馈控制，阻塞端不能采用前馈控制，</p></blockquote><blockquote><p>在某些讨论环境下，流通端又经常被大家称为末端</p></blockquote><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e0260d52f80e9397.q90-f9d858c02b714c06.webp" alt="23 阻塞端与流通端：你控控我，我控控你"></p><div class="logistics-image-caption" data-source-block="77PM06DCTK8TypTl2Lrb7b"><p>最简例子，其中配件机是阻塞端，塑形机是流通端</p></div><p><span class="mark-blue"><strong>在上面的最简例子中，配件机这条支路就是阻塞端，塑形机这条支路就是流通端。</strong></span><span class="mark-blue">阻塞端意即直接按照配件机最大速度生产铁零件，直到仓库装满为止，但是其仍然在“侦听”仓库中铁零件的数量，当仓库中铁零件被拿出时，它又会立刻开始生产。而流通端的塑形机则是拿到多少蓝铁块就做多少蓝铁瓶。</span></p><blockquote><p>当然，这要建立在输入流通端+阻塞端的总物料流量保持不变的情况下。</p></blockquote><p><strong>在使用优先级方案时，</strong><u><strong>优先输出端需要连接阻塞端生产，次优输出端需要连接流通端生产</strong></u><strong>。使用分流结构方案时，需要确保向</strong><u><strong>阻塞端提供充足的流量</strong></u><strong>，否则无法达成生产目的（见后）。</strong></p><p>一般而言，流通端的生产能力被设计为能够承接所有因阻塞而切换过来的物料流量，从而防止原料供给堵塞。当然，流通端也可以发生阻塞，从而使得物料转向第三条通路。这一情况下，流通端相对于第三条通路也成为一个阻塞端，而第三条通路成为新的流通端。此时，控制流程为外部限制→通路1→通路2→通路3。</p><table tabindex="0"><thead><tr><th></th><th>阻塞端</th><th>流通端</th></tr></thead><tbody><tr><td>相对生产优先级</td><td>高（意味着优先满足）</td><td>低（不意味着不生产）</td></tr><tr><td>状态</td><td>阻塞</td><td>流通</td></tr><tr><td>机器缓存</td><td>装满</td><td>空</td></tr><tr><td>生产受何限制</td><td>输出缓存阻塞，缺其他原料等</td><td>缺输入原料</td></tr><tr><td>流量表示（见2.5节）</td><td>XX-</td><td>YY+</td></tr><tr><td>因果性</td><td>由于受到外部限制而生产速度受限</td><td>由于仅能得到阻塞端剩余流量而生产速度受限</td></tr></tbody></table><blockquote><p>在2.1的例子中，可以认为蓝铁矿留在仓库是第三条通路</p></blockquote><p><span id="source-block-CAZ0d2JyieISTjVOQ2jJ3Q"></span></p><span class="logistics-source-anchor" id="汇流的角度" aria-hidden="true"></span><h3 id="汇流的角度" tabindex="-1">汇流的角度 <a class="header-anchor" href="#汇流的角度" aria-label="Permalink to &quot;汇流的角度&quot;">​</a></h3><p>作为对偶的一方，汇流器则表现得恰好相反。汇流器的特性，使得其阻塞的上游支路流量，取决于流通支路的流量，如下图中红矿的流量越高，蓝铁矿的流量就越低。</p><p>我们仍然把阻塞支路称为阻塞端，流通支路称为流通端。此时，若流通支路受到外部限制，则控制方向为：</p><p><span class="mark-purple"><strong>外部限制→流通端→阻塞端</strong></span></p><p>可见，在汇流器处控制方向发生了改变。这是由于满带对于汇流器的地位等价于空带对分流器的地位，即汇流器总能从满带获得物品，而分流器总能向空带输出物品。</p><p>此时的流量表示（见2.5节）也发生变化。阻塞端变为XX+，流通端变为YY-。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-86409d775be21737.q90-b3990af80072a4f0.webp" alt="23 阻塞端与流通端：你控控我，我控控你"></p><p>这种性质在阻塞流理论中也有充分研究（链接待补）。在阻塞生产中，我们还会遇到具有此类性质的机器：如下图所示，阻塞的源石粉末流量取决于壤晶的流量。这当然是显然的，因为给多少壤晶，才能消耗掉多少源石粉末。但是注意，这种控制行为我们完全可以不通过机器，而是只通过一个汇流器即可实现——只需要源石粉末形成阻塞。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-528b1cf648896905.q90-eb50c687009a94ef.webp" alt="23 阻塞端与流通端：你控控我，我控控你"></p><p>事实上，也并非需要两种材料，同一种材料也会出现此类情形，例如下图所示，下游最多接受18/m的赤铜瓶，上游赤铜块阻塞支的流量取决于流通支赤铜块的流量。图中10/m的流通支总能进入塑形机，而总消耗量为36/m，因而阻塞支的流量仅为26/m，这是一个常见的出货口不满速原因。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-45b149f8f087d0b8.q90-ea1c7e87c13b21c0.webp" alt="23 阻塞端与流通端：你控控我，我控控你"></p><p>不过，机器终归不完全是汇流器。从下面的例子来看，2/3的蓝铁矿流量去了配件机，1/3的蓝铁矿流量去了塑形机，它们二者最后又会在封装机中合成蓝药，此时配件机会间歇发生阻塞。但在下面构造的分汇流图中，2/3的蓝铁矿流量去上半，1/3流量去下半，最终二者汇流，实际并不出现阻塞。</p><p>那么，区别到底在哪呢？请读者开动聪明的小脑瓜想一想</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ccde73abc1fc2989.q90-963d3167ae95758f.webp" alt="23 阻塞端与流通端：你控控我，我控控你"></p><p><a href="/endfield-skydoc/zh/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking">2.2 花开两朵：切换型阻塞与平衡型阻塞</a></p><p><a href="/endfield-skydoc/zh/2-4-faster-than-light-upstream-propagation-of-blocking-signals">2.4 阻塞信号の“超光速”反向传播规律</a></p></div>',1)])])}const b=o(n,[["render",r]]);export{h as __pageData,b as default};
